{
  "concept": "A hash table with chaining resolves collisions by storing all keys that hash to the same slot in a linked list, so the hash function h alone determines how the keys partition into chains and thus the cost of every operation.",
  "figureType": "diagram",
  "elements": [
    "outer dark-gray ring labeled 'U (universe of keys)'",
    "inner light-gray circle labeled 'K (actual keys)'",
    "eight filled black key dots inside K labeled k1 through k8",
    "vertical hash table T drawn as a column of m slots, titled 'T'",
    "empty slots rendered with a diagonal hatch (nil)",
    "non-empty slots rendered as white cells with a rightward arrow to their chain",
    "arrow from each key dot in K to the slot h(k) it hashes to",
    "doubly linked list chains hanging off non-empty slots",
    "each list node drawn as a three-cell box: left-pointer cell, key-label cell, right-pointer cell",
    "diagonal slash marking null (nil) pointers at chain ends",
    "bidirectional arrows between consecutive nodes in each chain"
  ],
  "interactions": [
    {
      "id": "hashFunction",
      "type": "code_editor",
      "label": "Hash function h(k)",
      "entry_point": "hash(k)",
      "api": [
        { "op": "slotCount()", "does": "returns m, the number of slots in table T" },
        { "op": "keyValue(name)", "does": "returns the numeric value of a key like 'k5'" },
        { "op": "insert(slot, key)", "does": "prepend key to the chain at slot — the ONLY way to mutate the table" },
        { "op": "chainLength(slot)", "does": "returns the current number of nodes in the chain at slot" },
        { "op": "note(text)", "does": "attach a learner annotation to the current frame" }
      ],
      "frame": "the whole table T plus the single chain whose head insert(slot,key) just extended, with the arrow from the originating key in K highlighted",
      "input": { "label": "Keys in K", "default": "k1=1, k2=2, k3=3, k4=4, k5=5, k6=6, k7=7, k8=8" },
      "sample_code": "return k % 5;",
      "buggy_code": "return 0; // BUG: constant hash — every key collides into slot 0, one chain of length 8",
      "success_check": "for every slot s, its chain contains exactly the keys { k : hash(k) mod m == s }, inserted at the head in key order; a 'good' hash leaves no single chain holding all 8 keys",
      "teaches": "h(k) alone fixes the chain structure: editing the expression reroutes every arrow and rebuilds the chains live, so a poor hash visibly piles keys into one long chain while a good hash spreads them into short chains"
    },
    {
      "id": "runHash",
      "type": "button",
      "label": "Insert keys",
      "states": ["idle", "stepping", "done"],
      "default": "idle",
      "teaches": "Stepping the insertion shows keys arriving one at a time and stacking at the head of their chain, making collision accumulation a visible, ordered process rather than a static picture"
    },
    {
      "id": "revealMapping",
      "type": "hover",
      "teaches": "Hovering a key dot or a chain node reveals its numeric value and the slot h(k) it maps to, so the learner can verify exactly why each key landed in its chain under the current hash"
    }
  ],
  "demo_steps": [
    {
      "title": "Empty table, keys in K",
      "narration": "All eight actual keys sit in K inside the universe U, and table T is empty (every slot hatched nil). The hash function has not yet been applied.",
      "state": { "runHash": "idle" }
    },
    {
      "title": "Watch collisions build chains",
      "narration": "Step the insertion: each key is hashed and prepended to its slot's chain. Keys sharing a slot stack into a doubly linked list — collisions are resolved by chaining, not by finding a new slot.",
      "state": { "runHash": "stepping" }
    },
    {
      "title": "Final chained table",
      "narration": "With the default h(k) = k % 5 the keys spread across several short chains. Hover any node to confirm its key value and target slot.",
      "state": { "runHash": "done" }
    },
    {
      "title": "Break the hash, watch it degrade",
      "narration": "Now edit h(k) to a constant like 'return 0' and re-run: every arrow reroutes to slot 0 and one chain of length 8 forms — the table has silently degraded into a single linked list.",
      "state": { "runHash": "done" }
    }
  ],
  "keyInsight": "The hash function is the only thing that shapes the chains: a good h spreads keys into short lists (near O(1) search), while a poor h collapses them into one long list, turning the hash table into an ordinary linked list.",
  "reconstructionNotes": "Left: two concentric circles — a dark-gray outer ring labeled 'U (universe of keys)' and a light-gray inner disk labeled 'K (actual keys)' containing eight black dots k1..k8. Center: a tall vertical column titled 'T' of about 9-10 equal slots; empty slots filled with a diagonal hatch, occupied slots white with a rightward arrow. Right: doubly linked lists of 3-cell boxes (left-ptr | key | right-ptr) with a slash in null pointer cells and double-headed arrows between nodes; reproduce the look of one length-3 chain, a couple of length-2 chains, and a length-1 chain. Thin straight arrows cross from each key dot to its slot, and these arrows must reroute live when h(k) changes. Keep the gray/light contrast strong so U vs K reads instantly, and highlight the active chain plus its incoming key-arrow during each insertion frame."
}

