}

// ---------- arrow helpers ----------
function head(parent,x,y,ang,size,color){
  size=size||7; color=color||'#111';
  var a1=ang+Math.PI*0.82, a2=ang-Math.PI*0.82;
  var p1=[x+size*Math.cos(a1), y+size*Math.sin(a1)];
  var p2=[x+size*Math.cos(a2), y+size*Math.sin(a2)];
  parent.polygon([x+','+y, p1[0]+','+p1[1], p2[0]+','+p2[1]]).fill(color).stroke('none');
}
function arrow(parent,x1,y1,x2,y2,opt){
  opt=opt||{}; var col=opt.color||'#111', w=opt.width||1.4;
  parent.line(x1,y1,x2,y2).stroke({color:col,width:w});
  var ang=Math.atan2(y2-y1,x2-x1);
  head(parent,x2,y2,ang,opt.head||7,col);
  if(opt.double){ head(parent,x1,y1,ang+Math.PI,opt.head||7,col); }
}

// ---------- dynamic render ----------
function renderAll(highlightSlot, highlightKey){
