  var avail=W-CHAIN_X0-10;
  var step=Math.min(104, Math.floor((avail+22)/maxLen));
  var nodeW=Math.max(40, step-22);
  var ptrW=Math.max(12, Math.round(nodeW*0.26));
  var keyW=nodeW-2*ptrW;
  var nodeH=34;

  // table slots
  for(var s=0;s<M;s++){
    var y=TABLE_TOP+s*SLOT_H;
    var occupied = tableChains[s].length>0;
