(function(){
"use strict";
var W=1000, H=560;
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%').viewbox(0,0,W,H);
var M = 10;                       // number of slots in T
var TABLE_X=430, TABLE_W=44, TABLE_TOP=70, SLOT_H=44;
var CHAIN_X0=520;

// ---- key dot layout inside K ----
var KEY_POS = {
  k1:[150,205], k4:[178,262], k5:[252,248], k7:[214,290],
  k2:[186,330], k3:[272,330], k8:[232,352], k6:[150,360]
};
var keyList = [];                 // [{name,value}]
var hashFn = function(k){ return ((k%5)+5)%5; };
var tableChains = [];             // array of arrays of key names
for(var i=0;i<M;i++) tableChains.push([]);

function slotCenterY(s){ return TABLE_TOP + s*SLOT_H + SLOT_H/2; }
function parseKeys(src){
  var out=[]; var parts=String(src).split(',');
  for(var i=0;i<parts.length;i++){
    var p=parts[i].trim(); if(!p) continue;
    var eq=p.indexOf('='); if(eq<0) continue;
    var name=p.slice(0,eq).trim(); var val=parseFloat(p.slice(eq+1));
    if(name && isFinite(val)) out.push({name:name,value:val});
  }
  if(!out.length) out=[{name:'k1',value:1}];
  return out;
}
function slotOf(value){ try{ var s=hashFn(value); if(typeof s!=='number'||!isFinite(s)) return 0; return ((s%M)+M)%M; }catch(e){ return 0; } }

// ---------- static layer ----------
var gStatic = draw.group();
var gDyn = draw.group();

function halo(t){ return t.attr({'paint-order':'stroke',stroke:'#ffffff','stroke-width':3,'stroke-linejoin':'round'}); }

function buildStatic(){
  gStatic.clear();
  // U outer ring
  gStatic.circle(300).center(210,280).fill('#9a9a9a').stroke({color:'#333',width:1.5});
  // K inner disk
  gStatic.circle(210).center(210,280).fill('#e6e6e6').stroke({color:'#333',width:1.2});
  halo(gStatic.text('U').font({size:22,style:'italic',family:'Georgia'}).center(210,150).fill('#111'));
  halo(gStatic.text('(universe of keys)').font({size:15,family:'Georgia'}).center(210,178).fill('#111'));
  halo(gStatic.text('K').font({size:20,style:'italic',family:'Georgia'}).center(120,262).fill('#111'));
  halo(gStatic.text('(actual').font({size:14,family:'Georgia'}).center(120,284).fill('#111'));
  halo(gStatic.text('keys)').font({size:14,family:'Georgia'}).center(120,304).fill('#111'));
  halo(gStatic.text('T').font({size:22,style:'italic',family:'Georgia'}).center(TABLE_X+TABLE_W/2,52).fill('#111'));
  // key dots
  for(var i=0;i<keyList.length;i++){
    (function(kd){
      var pos=KEY_POS[kd.name]||[210,280];
      var dot=gStatic.circle(11).center(pos[0],pos[1]).fill('#111').css('cursor','pointer');
      halo(gStatic.text(kd.name.replace('k','k')).font({size:16,style:'italic',family:'Georgia'})
