    })(keyList[i]);
  }
}

// ---------- arrow helpers ----------
function head(parent,x,y,ang,size,color){
  size=size||7; color=color||'#111';
  var a1=ang+Math.PI*0.82, a2=ang-Math.PI*0.82;
  var p1=[x+size*Math.cos(a1), y+size*Math.sin(a1)];
  var p2=[x+size*Math.cos(a2), y+size*Math.sin(a2)];
  parent.polygon([x+','+y, p1[0]+','+p1[1], p2[0]+','+p2[1]]).fill(color).stroke('none');
}
function arrow(parent,x1,y1,x2,y2,opt){
  opt=opt||{}; var col=opt.color||'#111', w=opt.width||1.4;
  parent.line(x1,y1,x2,y2).stroke({color:col,width:w});
  var ang=Math.atan2(y2-y1,x2-x1);
  head(parent,x2,y2,ang,opt.head||7,col);
  if(opt.double){ head(parent,x1,y1,ang+Math.PI,opt.head||7,col); }
}

// ---------- dynamic render ----------
function renderAll(highlightSlot, highlightKey){
  gDyn.clear();
  // compute per-chain layout step based on max length
  var maxLen=1; for(var s=0;s<M;s++) maxLen=Math.max(maxLen, tableChains[s].length);
  var avail=W-CHAIN_X0-10;
  var step=Math.min(104, Math.floor((avail+22)/maxLen));
  var nodeW=Math.max(40, step-22);
  var ptrW=Math.max(12, Math.round(nodeW*0.26));
  var keyW=nodeW-2*ptrW;
  var nodeH=34;

  // table slots
  for(var s=0;s<M;s++){
    var y=TABLE_TOP+s*SLOT_H;
    var occupied = tableChains[s].length>0;
    var rect=gDyn.rect(TABLE_W,SLOT_H).move(TABLE_X,y).stroke({color:'#333',width:1.2});
    if(occupied){
      rect.fill((highlightSlot===s)?'#fff6cc':'#f2f2f2');
      // rightward arrow to chain head
      arrow(gDyn, TABLE_X+TABLE_W/2, y+SLOT_H/2, CHAIN_X0-6, y+SLOT_H/2, {color:'#111',width:1.4});
    } else {
      rect.fill((highlightSlot===s)?'#fff6cc':'#9a9a9a');
      gDyn.line(TABLE_X+8, y+SLOT_H-8, TABLE_X+TABLE_W-8, y+8).stroke({color:'#222',width:1.4});
    }
  }

  // chains
  for(var s2=0;s2<M;s2++){
    var chain=tableChains[s2]; if(!chain.length) continue;
    var cy=slotCenterY(s2);
    var prevRight=null;
    for(var n=0;n<chain.length;n++){
      var nx=CHAIN_X0 + n*step;
      var ny=cy-nodeH/2;
      var isHead=(n===0);
      var nodeFill=(highlightSlot===s2)?'#fff6cc':'#ececec';
      gDyn.rect(nodeW,nodeH).move(nx,ny).fill(nodeFill).stroke({color:'#333',width:1.2});
      gDyn.line(nx+ptrW,ny,nx+ptrW,ny+nodeH).stroke({color:'#333',width:1});
      gDyn.line(nx+ptrW+keyW,ny,nx+ptrW+keyW,ny+nodeH).stroke({color:'#333',width:1});
      // key label
      var kl=halo(gDyn.text(chain[n]).font({size:Math.min(16,Math.max(10,keyW*0.5)),style:'italic',family:'Georgia'})
        .center(nx+ptrW+keyW/2, cy).fill('#111'));
      // null slashes
      if(n===0){ gDyn.line(nx+4,ny+nodeH-5,nx+ptrW-4,ny+5).stroke({color:'#222',width:1.2}); }
      if(n===chain.length-1){ gDyn.line(nx+ptrW+keyW+4,ny+nodeH-5,nx+nodeW-4,ny+5).stroke({color:'#222',width:1.2}); }
      // hover on node
      (function(name,slot){
        var hv=gDyn.rect(nodeW,nodeH).move(nx,ny).fill('transparent').css('cursor','pointer');
        var val=0; for(var q=0;q<keyList.length;q++) if(keyList[q].name===name) val=keyList[q].value;
        hv.on('mousemove',function(e){ showTooltip(name+' (value '+val+') stored in slot '+slot, e); });
        hv.on('mouseleave',hideTooltip);
        hv.on('click',function(){ showPopup('Chain node '+name,'Key '+name+' has value '+val+' and lives in slot '+slot+' under the current hash.'); });
      })(chain[n], s2);
      // double arrow between consecutive nodes
      if(prevRight!==null){
        var ay=cy;
        arrow(gDyn, prevRight+2, ay-4, nx-2, ay-4, {color:'#111',width:1.2});
        arrow(gDyn, nx-2, ay+4, prevRight+2, ay+4, {color:'#111',width:1.2});
      }
      prevRight=nx+nodeW;
    }
  }

  // arrows from each key dot to its slot
  for(var k=0;k<keyList.length;k++){
    var kd=keyList[k]; var pos=KEY_POS[kd.name]||[210,280];
    var sl=slotOf(kd.value);
    var ty=slotCenterY(sl);
    var active=(highlightKey===kd.name);
    arrow(gDyn, pos[0]+6, pos[1], TABLE_X-3, ty, {color:active?'#d00':'#111', width:active?2.2:1.1, head:active?8:6});
  }
}

function rebuildFromHash(){
  for(var s=0;s<M;s++) tableChains[s]=[];
  for(var i=0;i<keyList.length;i++){
    var sl=slotOf(keyList[i].value);
