var draw = SVG().addTo(document.getElementById('container')).size('100%','100%').viewbox(0,0,W,H);
var M = 10;
var TABLE_X=465, TABLE_W=50, TABLE_TOP=38, SLOT_H=42;
var CHAIN_X0=558;
var NODE_CELL=30, NODE_H=36, NODE_W=NODE_CELL*3, NODE_GAP=28;

// Source-exact default chains (append order matching the textbook figure)
var SOURCE_CHAINS = {1:['k1','k4'], 5:['k5','k2','k7'], 7:['k3'], 8:['k8','k6']};
var SOURCE_SLOT = {k1:1, k2:5, k3:7, k4:1, k5:5, k6:8, k7:5, k8:8};

