function slotOfKey(name){
  if(useSourceDefault && SOURCE_SLOT[name]!==undefined) return SOURCE_SLOT[name];
  for(var i=0;i<keyList.length;i++) if(keyList[i].name===name) return slotOf(keyList[i].value);
  return 0;
}

var gStatic = draw.group();
var gDyn = draw.group();

function halo(t){ return t.attr({'paint-order':'stroke',stroke:'#ffffff','stroke-width':3,'stroke-linejoin':'round'}); }

function subLabel(parent, base, sub, cx, cy, size, anchor){
  size = size||16;
  var g = parent.group();
  var t1 = g.text(base).font({size:size, style:'italic', family:'Georgia,serif'}).fill('#111');
  var t2 = g.text(sub).font({size:Math.round(size*0.62), family:'Georgia,serif'}).fill('#111');
  var w1 = t1.length()*0.58;
  var w2 = t2.length()*0.42;
  var total = w1 + w2;
  var startX = (anchor==='end') ? cx - total : (anchor==='middle') ? cx - total/2 : cx;
  t1.move(startX, cy - size*0.42);
  t2.move(startX + w1, cy - size*0.42 + size*0.28);
  halo(t1); halo(t2);
  return g;
}

function buildStatic(){
  gStatic.clear();
  // U outer ring
  gStatic.circle(360).center(195,265).fill('#8a8a8a').stroke({color:'#333',width:1.5});
  // K inner disk
  gStatic.circle(256).center(195,280).fill('#e8e8e8').stroke({color:'#333',width:1.2});
  // U label at top of ring
  halo(gStatic.text('U').font({size:24,style:'italic',family:'Georgia,serif'}).center(195,105).fill('#111'));
  halo(gStatic.text('(universe of keys)').font({size:14,family:'Georgia,serif'}).center(195,130).fill('#111'));
  // K label on left
  halo(gStatic.text('K').font({size:22,style:'italic',family:'Georgia,serif'}).center(98,262).fill('#111'));
  halo(gStatic.text('(actual').font({size:13,family:'Georgia,serif'}).center(98,284).fill('#111'));
  halo(gStatic.text('keys)').font({size:13,family:'Georgia,serif'}).center(98,302).fill('#111'));
  // T label
  halo(gStatic.text('T').font({size:24,style:'italic',family:'Georgia,serif'}).center(TABLE_X+TABLE_W/2,24).fill('#111'));
  // Key dots with subscript labels
  for(var i=0;i<keyList.length;i++){
    (function(kd){
      var pos=KEY_POS[kd.name]||[195,280];
      var num = kd.name.replace('k','');
      var dot=gStatic.circle(10).center(pos[0],pos[1]).fill('#111').css('cursor','pointer');
      subLabel(gStatic, 'k', num, pos[0]-14, pos[1]+1, 16, 'end');
      dot.on('mousemove',function(e){ showTooltip(kd.name+' = '+kd.value+'  →  slot '+slotOfKey(kd.name), e); });
