      rect.fill((highlightSlot===s)?'#fff6cc':'#f5f5f5');
      arrow(gDyn, TABLE_X+TABLE_W/2, y+SLOT_H/2, CHAIN_X0-8, y+SLOT_H/2, {color:'#111',width:1.4});
    } else {
      rect.fill((highlightSlot===s)?'#fff6cc':'#9a9a9a');
      gDyn.line(TABLE_X+8, y+SLOT_H-8, TABLE_X+TABLE_W-8, y+8).stroke({color:'#333',width:1.6});
