        arrow(gDyn, nx-3, ay2, prevRight+3, ay2, {color:'#111',width:1.2,head:6});
      }
      prevRight=nx+NODE_W;
    }
  }

  // Arrows from key dots to slots
  for(var k=0;k<keyList.length;k++){
    var kd=keyList[k]; var pos=KEY_POS[kd.name]||[195,280];
    var sl=slotOfKey(kd.name);
    var ty=slotCenterY(sl);
    var active=(highlightKey===kd.name);
    arrow(gDyn, pos[0]+6, pos[1], TABLE_X-4, ty, {color:active?'#c00':'#111', width:active?2.2:1.0, head:active?8:5});
