function slotCenterY(s){ return TABLE_TOP + s*SLOT_H + SLOT_H/2; }
function parseKeys(src){
  var out=[]; var parts=String(src).split(',');
  for(var i=0;i<parts.length;i++){
    var p=parts[i].trim(); if(!p) continue;
    var eq=p.indexOf('='); if(eq<0) continue;
    var name=p.slice(0,eq).trim(); var val=parseFloat(p.slice(eq+1));
    if(name && isFinite(val)) out.push({name:name,value:val});
  }
  if(!out.length) out=[{name:'k1',value:1}];
  return out;
}
function slotOf(value){ try{ var s=hashFn(value); if(typeof s!=='number'||!isFinite(s)) return 0; return ((s%M)+M)%M; }catch(e){ return 0; } }
