    var ty=slotCenterY(sl);
    var active=(highlightKey===kd.name);
    arrow(gDyn, pos[0]+6, pos[1], TABLE_X-4, ty, {color:active?'#c00':'#111', width:active?2.2:1.0, head:active?8:5});
  }
}

function buildSourceDefault(){
  for(var s=0;s<M;s++) tableChains[s]=[];
  for(var sl in SOURCE_CHAINS){
    tableChains[+sl] = SOURCE_CHAINS[sl].slice();
  }
}

function rebuildFromHash(){
  for(var s=0;s<M;s++) tableChains[s]=[];
  for(var i=0;i<keyList.length;i++){
    var sl=slotOf(keyList[i].value);
    tableChains[sl].push(keyList[i].name);
  }
}

// ---------- runHash stepping ----------
var runState='idle'; var stepTimer=null;
function setRunButton(){
  var b=document.getElementById('runHashInput');
  b.textContent = runState==='idle'?'Insert keys':(runState==='stepping'?'Inserting…':'Done ✓');
  b.classList.toggle('active', runState==='done');
}
function applyKeysFromInput(){ keyList=parseKeys(document.getElementById('hashFunctionInput').value); buildStatic(); }
function compileFromEditor(){
  var src=document.getElementById('hashFunctionCode').value;
  try{ hashFn=compileExpr(src,['k']); return true; }
  catch(e){ showPopup('Hash parse error', e.message); return false; }
}
function trigger_runHash(){
  if(runState==='stepping') return;
  useSourceDefault=false;
  applyKeysFromInput();
  if(!compileFromEditor()) return;
  for(var s=0;s<M;s++) tableChains[s]=[];
  runState='stepping'; setRunButton();
  var idx=0;
  clearInterval(stepTimer);
  function tick(){
    if(idx>=keyList.length){ runState='done'; setRunButton(); renderAll(); clearInterval(stepTimer); return; }
    var kd=keyList[idx]; var sl=slotOf(kd.value);
    tableChains[sl].push(kd.name);
    renderAll(sl, kd.name);
    idx++;
  }
  stepTimer=setInterval(tick, 380);
}
function buildInstant(){
  useSourceDefault=false;
  applyKeysFromInput(); compileFromEditor(); rebuildFromHash(); runState='done'; setRunButton(); renderAll();
}
function clearTable(){
  for(var s=0;s<M;s++) tableChains[s]=[]; runState='idle'; setRunButton(); renderAll();
}

// ---------- code editor + worker + playback ----------
var SAMPLE='return k % 5;';
var BUGGY='return 0; // BUG: constant hash — every key collides into slot 0';
var STARTER='// write the body of hash(k)\nreturn ';
function setTab(t){
  var ta=document.getElementById('hashFunctionCode');
  ta.value = t==='sample'?SAMPLE : t==='buggy'?BUGGY : STARTER;
}
var frames=[]; var curFrame=0; var playTimer=null; var pbSpeedVal=300;
function setStatus(s,col){ var e=document.getElementById('hfStatus'); e.textContent='status: '+s; e.style.color=col||'#555'; }
function runCodeEditor(){
  useSourceDefault=false;
  applyKeysFromInput();
  var code=document.getElementById('hashFunctionCode').value;
  var keysJSON=JSON.stringify(keyList);
  var workerSrc =
    'var M='+M+';var keys='+keysJSON+';var chains=[];for(var i=0;i<M;i++)chains.push([]);var frames=[];'+
    'function deep(){return chains.map(function(c){return c.slice();});}'+
    'function push(kind,indices,msg){if(frames.length>4000)throw new Error("too many frames");frames.push({kind:kind,state:deep(),indices:indices,message:msg});}'+
    'function slotCount(){push("slotCount",[],"slotCount() -> "+M);return M;}'+
    'function keyValue(n){for(var i=0;i<keys.length;i++)if(keys[i].name===n){push("keyValue",[],"keyValue("+n+") -> "+keys[i].value);return keys[i].value;}push("keyValue",[],"keyValue("+n+") -> ?");return NaN;}'+
    'function chainLength(s){push("chainLength",[s],"chainLength("+s+") -> "+chains[s].length);return chains[s].length;}'+
    'function insert(s,k){if(s<0||s>=M)throw new Error("slot out of range: "+s);chains[s].push(k);push("insert",[s],"insert "+k+" at slot "+s+" -> length "+chains[s].length);}'+
    'function note(t){push("note",[],"note: "+t);}'+
    'push("init",[],"start: empty table, m="+M);'+
    'function hash(k){'+code+'\n}'+
    'try{for(var i=0;i<keys.length;i++){var v=keys[i].value;var s=hash(v);if(typeof s!=="number"||!isFinite(s))throw new Error("hash returned non-number for "+keys[i].name);s=((s%M)+M)%M;insert(s,keys[i].name);}postMessage({ok:true,frames:frames});}'+
    'catch(e){postMessage({ok:false,error:String(e&&e.message||e),frames:frames});}';
  setStatus('running','#b07000');
  document.getElementById('hashFunctionRun').disabled=true;
  frames=[]; curFrame=0; updatePb();
  var blob=new Blob([workerSrc],{type:'application/javascript'});
  var url=URL.createObjectURL(blob);
  var w=new Worker(url);
  var to=setTimeout(function(){ w.terminate(); URL.revokeObjectURL(url); setStatus('timeout','#c00'); document.getElementById('hashFunctionRun').disabled=false; },2000);
  w.onmessage=function(ev){
    clearTimeout(to); w.terminate(); URL.revokeObjectURL(url);
    document.getElementById('hashFunctionRun').disabled=false;
    var d=ev.data; frames=d.frames||[];
    if(d.ok){
      var last=frames[frames.length-1];
      var allInOne=false; for(var s2=0;s2<M;s2++) if(last.state[s2].length===keyList.length) allInOne=true;
      setStatus(allInOne?'wrong answer (degraded)':'correct', allInOne?'#c00':'#080');
    } else { setStatus('error: '+d.error,'#c00'); }
    curFrame=frames.length-1; updatePb(); drawFrame(curFrame);
  };
  w.onerror=function(e){ clearTimeout(to); URL.revokeObjectURL(url); document.getElementById('hashFunctionRun').disabled=false; setStatus('error','#c00'); };
}
function drawFrame(i){
  if(!frames.length){ renderAll(); return; }
  i=Math.max(0,Math.min(frames.length-1,i));
  var f=frames[i];
  for(var s=0;s<M;s++) tableChains[s]=(f.state[s]||[]).slice();
  var hs=(f.indices&&f.indices.length)?f.indices[0]:null;
  var hk=null;
  if(f.kind==='insert' && hs!==null && tableChains[hs].length) hk=tableChains[hs][tableChains[hs].length-1];
  renderAll(hs,hk);
}
function updatePb(){
  document.getElementById('pbCounter').textContent='frame '+(frames.length?curFrame+1:0)+' / '+frames.length;
  document.getElementById('pbCaption').textContent= frames.length? frames[curFrame].message : 'Run the hash to record frames.';
  var log=document.getElementById('pbLog'); log.innerHTML='';
  for(var i=0;i<frames.length;i++){
    var div=document.createElement('div');
    div.textContent=(i+1)+'. '+frames[i].message;
    if(i===curFrame) div.style.fontWeight='bold';
    log.appendChild(div);
  }
  log.scrollTop=log.scrollHeight;
}
function pbFirst(){ stopPlay(); curFrame=0; updatePb(); drawFrame(0); }
function pbPrev(){ stopPlay(); if(curFrame>0)curFrame--; updatePb(); drawFrame(curFrame); }
function pbNext(){ stopPlay(); if(curFrame<frames.length-1)curFrame++; updatePb(); drawFrame(curFrame); }
function pbPlay(){
  if(playTimer){ stopPlay(); return; }
  if(curFrame>=frames.length-1) curFrame=0;
  document.getElementById('pbPlayBtn').textContent='⏸';
  playTimer=setInterval(function(){ if(curFrame<frames.length-1){curFrame++;updatePb();drawFrame(curFrame);} else stopPlay(); }, pbSpeedVal);
}
function stopPlay(){ if(playTimer){clearInterval(playTimer);playTimer=null;} document.getElementById('pbPlayBtn').textContent='▶'; }

// ---------- demo steps ----------
var steps=[
  {t:'Empty table, keys in K', n:'All eight actual keys sit in K inside the universe U, and table T is empty (every slot hatched nil). The hash function has not yet been applied.', go:function(){ document.getElementById('hashFunctionCode').value=SAMPLE; useSourceDefault=false; clearTable(); }},
  {t:'Watch collisions build chains', n:'Step the insertion: each key is hashed and appended to its slot\u2019s chain. Keys sharing a slot stack into a doubly linked list \u2014 collisions are resolved by chaining, not by finding a new slot.', go:function(){ document.getElementById('hashFunctionCode').value=SAMPLE; runState='idle'; trigger_runHash(); }},
  {t:'Final chained table', n:'With the default h(k) = k % 5 the keys spread across several short chains. Hover any node to confirm its key value and target slot.', go:function(){ useSourceDefault=true; applyKeysFromInput(); buildSourceDefault(); runState='done'; setRunButton(); renderAll(); }},
  {t:'Break the hash, watch it degrade', n:'Now edit h(k) to a constant like \u2018return 0\u2019 and re-run: every arrow reroutes to slot 0 and one chain of length 8 forms \u2014 the table has silently degraded into a single linked list.', go:function(){ document.getElementById('hashFunctionCode').value=BUGGY; buildInstant(); }}
];
var curStep=2;
function showStep(i){
  curStep=Math.max(0,Math.min(steps.length-1,i));
  document.getElementById('stepLabel').textContent=(curStep+1)+' / '+steps.length;
  document.getElementById('demoNarration').textContent=steps[curStep].n;
  steps[curStep].go();
}
window.nextStep=function(){ showStep(curStep+1); };
window.prevStep=function(){ showStep(curStep-1); };

window.trigger_runHash=trigger_runHash;
window.runCodeEditor=runCodeEditor;
window.setTab=setTab;
window.pbFirst=pbFirst; window.pbPrev=pbPrev; window.pbNext=pbNext; window.pbPlay=pbPlay;

// ---------- init ----------
applyKeysFromInput();
buildStatic();
showStep(2);
window.__markRendered();
})();
// @FIGURE_CODE_END

