// @FIGURE_CODE_BEGIN
(function(){
"use strict";
// Viewbox ratio ~1.32 so the diagram fills the (roughly square) docked container
// instead of letterboxing into a tiny centred strip.
var W=900, H=680;
var draw = SVG().addTo(document.getElementById('container')).size('100%','100%').viewbox(0,0,W,H);

var M = 10;
var TABLE_X=470, TABLE_W=56, TABLE_TOP=50, SLOT_H=58;
var CHAIN_X0=560;
var NODE_CELL=30, NODE_H=44, NODE_W=NODE_CELL*3, NODE_GAP=22;
var UCX=210, UCY=360, U_R=180, K_R=125;

var SOURCE_CHAINS = {1:['k1','k4'], 5:['k5','k2','k7'], 7:['k3'], 8:['k8','k6']};
var SOURCE_SLOT = {k1:1, k2:5, k3:7, k4:1, k5:5, k6:8, k7:5, k8:8};
var KEY_POS = {
  k1:[150,300], k4:[170,345], k5:[250,335], k7:[225,375],
  k2:[185,415], k3:[265,405], k8:[225,440], k6:[150,455]
};
var keyList = [];
var hashFn = function(k){ return ((k%5)+5)%5; };
var tableChains = [];
for(var i=0;i<M;i++) tableChains.push([]);
var useSourceDefault = true;

function slotCenterY(s){ return TABLE_TOP + s*SLOT_H + SLOT_H/2; }
function parseKeys(src){
  var out=[]; var parts=String(src).split(',');
  for(var i=0;i<parts.length;i++){
    var p=parts[i].trim(); if(!p) continue;
    var eq=p.indexOf('='); if(eq<0) continue;
    var name=p.slice(0,eq).trim(); var val=parseFloat(p.slice(eq+1));
    if(name && isFinite(val)) out.push({name:name,value:val});
  }
  if(!out.length) out=[{name:'k1',value:1}];
  return out;
}
function slotOf(value){ try{ var s=hashFn(value); if(typeof s!=='number'||!isFinite(s)) return 0; return ((s%M)+M)%M; }catch(e){ return 0; } }
function slotOfKey(name){
  if(useSourceDefault && SOURCE_SLOT[name]!==undefined) return SOURCE_SLOT[name];
  for(var i=0;i<keyList.length;i++) if(keyList[i].name===name) return slotOf(keyList[i].value);
  return 0;
}

var gStatic = draw.group();
var gDyn = draw.group();

function halo(t){ return t.attr({'paint-order':'stroke',stroke:'#ffffff','stroke-width':3.5,'stroke-linejoin':'round'}); }

function subLabel(parent, base, sub, cx, cy, size, anchor){
  size = size||17;
  var g = parent.group();
  var t1 = g.text(base).font({size:size, style:'italic', family:'Georgia,serif'}).fill('#111');
  var t2 = g.text(sub).font({size:Math.round(size*0.62), family:'Georgia,serif'}).fill('#111');
  var w1 = t1.length()*0.58;
  var w2 = t2.length()*0.42;
  var total = w1 + w2;
  var startX = (anchor==='end') ? cx - total : (anchor==='middle') ? cx - total/2 : cx;
  t1.move(startX, cy - size*0.42);
  t2.move(startX + w1, cy - size*0.42 + size*0.30);
  halo(t1); halo(t2);
  return g;
}

function buildStatic(){
  gStatic.clear();
  // U outer ring
  gStatic.circle(U_R*2).center(UCX,UCY).fill('#8a8a8a').stroke({color:'#333',width:1.6});
  // K inner disk
  gStatic.circle(K_R*2).center(UCX,UCY+12).fill('#e8e8e8').stroke({color:'#333',width:1.3});
  // U label in the gray band (between outer top and inner top), clear of strokes
  halo(gStatic.text('U').font({size:28,style:'italic',family:'Georgia,serif'}).center(UCX,UCY-U_R+30).fill('#111'));
  halo(gStatic.text('(universe of keys)').font({size:16,family:'Georgia,serif'}).center(UCX,UCY-U_R+58).fill('#111'));
  // K label inside the light disk, left side, clear of the inner stroke
  halo(gStatic.text('K').font({size:26,style:'italic',family:'Georgia,serif'}).center(UCX-K_R+50,UCY-18).fill('#111'));
  halo(gStatic.text('(actual').font({size:15,family:'Georgia,serif'}).center(UCX-K_R+50,UCY+6).fill('#111'));
  halo(gStatic.text('keys)').font({size:15,family:'Georgia,serif'}).center(UCX-K_R+50,UCY+26).fill('#111'));
  // T label
  halo(gStatic.text('T').font({size:28,style:'italic',family:'Georgia,serif'}).center(TABLE_X+TABLE_W/2,TABLE_TOP-16).fill('#111'));
  // Key dots with subscript labels
  for(var i=0;i<keyList.length;i++){
    (function(kd){
      var pos=KEY_POS[kd.name]||[UCX,UCY];
      var num = kd.name.replace('k','');
      var dot=gStatic.circle(11).center(pos[0],pos[1]).fill('#111').css('cursor','pointer');
      subLabel(gStatic, 'k', num, pos[0]-15, pos[1]+1, 17, 'end');
      dot.on('mousemove',function(e){ showTooltip(kd.name+' = '+kd.value+'  →  slot '+slotOfKey(kd.name), e); });
      dot.on('mouseleave',hideTooltip);
      dot.on('click',function(){ showPopup('Key '+kd.name,'Numeric value '+kd.value+'. Under the current hash it maps to slot '+slotOfKey(kd.name)+'.'); });
    })(keyList[i]);
  }
}

function head(parent,x,y,ang,size,color){
  size=size||7; color=color||'#111';
  var a1=ang+Math.PI*0.82, a2=ang-Math.PI*0.82;
  var p1=[x+size*Math.cos(a1), y+size*Math.sin(a1)];
  var p2=[x+size*Math.cos(a2), y+size*Math.sin(a2)];
  parent.polygon([x+','+y, p1[0]+','+p1[1], p2[0]+','+p2[1]]).fill(color).stroke('none');
}
function arrow(parent,x1,y1,x2,y2,opt){
  opt=opt||{}; var col=opt.color||'#111', w=opt.width||1.4;
  parent.line(x1,y1,x2,y2).stroke({color:col,width:w});
  var ang=Math.atan2(y2-y1,x2-x1);
  head(parent,x2,y2,ang,opt.head||7,col);
}

function renderAll(highlightSlot, highlightKey){
  gDyn.clear();
  // Table slots
  for(var s=0;s<M;s++){
    var y=TABLE_TOP+s*SLOT_H;
    var occupied = tableChains[s].length>0;
    var rect=gDyn.rect(TABLE_W,SLOT_H).move(TABLE_X,y).stroke({color:'#333',width:1.3});
    if(occupied){
      rect.fill((highlightSlot===s)?'#fff3c0':'#f5f5f5');
      arrow(gDyn, TABLE_X+TABLE_W/2, y+SLOT_H/2, CHAIN_X0-9, y+SLOT_H/2, {color:'#111',width:1.5});
    } else {
      rect.fill((highlightSlot===s)?'#fff3c0':'#9a9a9a');
      gDyn.line(TABLE_X+9, y+SLOT_H-9, TABLE_X+TABLE_W-9, y+9).stroke({color:'#333',width:1.7});
    }
  }

  // Chains
  for(var s2=0;s2<M;s2++){
    var chain=tableChains[s2]; if(!chain.length) continue;
    var cy=slotCenterY(s2);
    var prevRight=null;
    for(var n=0;n<chain.length;n++){
      var nx=CHAIN_X0 + n*(NODE_W+NODE_GAP);
      var ny=cy-NODE_H/2;
      var nodeFill=(highlightSlot===s2)?'#fff3c0':'#ececec';
      gDyn.rect(NODE_W,NODE_H).move(nx,ny).fill(nodeFill).stroke({color:'#333',width:1.3});
      gDyn.line(nx+NODE_CELL,ny,nx+NODE_CELL,ny+NODE_H).stroke({color:'#333',width:1});
      gDyn.line(nx+2*NODE_CELL,ny,nx+2*NODE_CELL,ny+NODE_H).stroke({color:'#333',width:1});
      var knum = chain[n].replace('k','');
      subLabel(gDyn, 'k', knum, nx+NODE_CELL+NODE_CELL/2, cy+1, 16, 'middle');
      if(n===0){ gDyn.line(nx+6,ny+NODE_H-6,nx+NODE_CELL-6,ny+6).stroke({color:'#333',width:1.5}); }
      if(n===chain.length-1){ gDyn.line(nx+2*NODE_CELL+6,ny+NODE_H-6,nx+NODE_W-6,ny+6).stroke({color:'#333',width:1.5}); }
      (function(name,slot){
        var hv=gDyn.rect(NODE_W,NODE_H).move(nx,ny).fill('transparent').css('cursor','pointer');
        var val=0; for(var q=0;q<keyList.length;q++) if(keyList[q].name===name) val=keyList[q].value;
        hv.on('mousemove',function(e){ showTooltip(name+' (value '+val+') in slot '+slot, e); });
        hv.on('mouseleave',hideTooltip);
        hv.on('click',function(){ showPopup('Chain node '+name,'Key '+name+' has value '+val+' and lives in slot '+slot+'.'); });
      })(chain[n], s2);
      if(prevRight!==null){
        var ay1=cy-6, ay2=cy+6;
        arrow(gDyn, prevRight+3, ay1, nx-3, ay1, {color:'#111',width:1.3,head:6});
        arrow(gDyn, nx-3, ay2, prevRight+3, ay2, {color:'#111',width:1.3,head:6});
      }
      prevRight=nx+NODE_W;
    }
  }

  // Arrows from key dots to slots
  for(var k=0;k<keyList.length;k++){
    var kd=keyList[k]; var pos=KEY_POS[kd.name]||[UCX,UCY];
    var sl=slotOfKey(kd.name);
    var ty=slotCenterY(sl);
    var active=(highlightKey===kd.name);
    arrow(gDyn, pos[0]+7, pos[1], TABLE_X-5, ty, {color:active?'#c00':'#111', width:active?2.4:1.0, head:active?9:5});
  }
}

function buildSourceDefault(){
  for(var s=0;s<M;s++) tableChains[s]=[];
  for(var sl in SOURCE_CHAINS){ tableChains[+sl] = SOURCE_CHAINS[sl].slice(); }
}
function rebuildFromHash(){
  for(var s=0;s<M;s++) tableChains[s]=[];
  for(var i=0;i<keyList.length;i++){ tableChains[slotOf(keyList[i].value)].push(keyList[i].name); }
}

var runState='idle'; var stepTimer=null;
function setRunButton(){
  var b=document.getElementById('runHashInput');
  b.textContent = runState==='idle'?'Insert keys':(runState==='stepping'?'Inserting…':'Done ✓');
  b.classList.toggle('active', runState==='done');
}
function applyKeysFromInput(){ keyList=parseKeys(document.getElementById('hashFunctionInput').value); buildStatic(); }
function compileFromEditor(){
  var src=document.getElementById('hashFunctionCode').value;
  try{ hashFn=compileExpr(src,['k']); return true; }
  catch(e){ showPopup('Hash parse error', e.message); return false; }
}
function trigger_runHash(){
  if(runState==='stepping') return;
  useSourceDefault=false;
  applyKeysFromInput();
  if(!compileFromEditor()) return;
  for(var s=0;s<M;s++) tableChains[s]=[];
  runState='stepping'; setRunButton();
  var idx=0;
  clearInterval(stepTimer);
  function tick(){
    if(idx>=keyList.length){ runState='done'; setRunButton(); renderAll(); clearInterval(stepTimer); return; }
    var kd=keyList[idx]; var sl=slotOf(kd.value);
    tableChains[sl].push(kd.name);
    renderAll(sl, kd.name);
    idx++;
  }
  stepTimer=setInterval(tick, 380);
}
function buildInstant(){
  useSourceDefault=false;
  applyKeysFromInput(); compileFromEditor(); rebuildFromHash(); runState='done'; setRunButton(); renderAll();
}
